Lemma W2_awin : forall lo (sp : word) fb, aceil <= lo -> aceil <= fb + 8 -> Forall awin (rs_W2 lo sp fb).
Proof.
  intros lo sp fb H1 H2. unfold rs_W2.
  apply Forall_cons; [apply awin_stack; exact H1|]. apply Forall_cons; [apply awin_stack; exact H2|]. apply Forall_cons; [exact (proj1 pwin_httpcat)| apply Forall_nil].
Qed.

(* [comment removed for export] *)
Lemma W2_disjoint_app : forall lo (sp : word) fb A n, aceil <= lo -> aceil <= fb + 8 -> AG_HTTP_CAT + 64 <= A -> A + n <= aceil ->
  disjoint_from (rs_W2 lo sp fb) A n.
Proof. intros lo sp fb A n H1 H2 H3 H4. unfold rs_W2. cbn [disjoint_from fst snd]. repeat split; lia. Qed.

(* [comment removed for export] *)
Lemma W2_disjoint_img : forall lo (sp : word) fb A n, aceil <= lo -> aceil <= fb + 8 -> A + n <= AG_HTTP_CAT -> disjoint_from (rs_W2 lo sp fb) A n.
Proof.
  intros lo sp fb A n H1 H2 H3. pose proof aceil_facts as (AF & _). unfold rs_W2. cbn [disjoint_from fst snd]. unfold AG_HTTP_CAT in *. repeat split; lia.
Qed.

(* [comment removed for export] *)
Lemma W2_disjoint_hi : forall lo (sp : word) fb A n, aceil <= lo -> bv_unsigned sp + -104 <= A -> lo <= bv_unsigned sp + -104 ->
  (A + n <= fb + 8 \/ fb + 24 <= A) -> disjoint_from (rs_W2 lo sp fb) A n.
Proof.
  intros lo sp fb A n H1 H2 H3 H4. pose proof aceil_facts as (AF & _). unfold rs_W2. cbn [disjoint_from fst snd]. unfold AG_HTTP_CAT in *. repeat split; lia.
Qed.

(* [comment removed for export] *)
Lemma W2_disjoint_sh : forall lo (sp : word) fb A n, aceil <= lo -> aceil <= fb + 8 -> 0 <= A -> 0 <= n -> A + n <= AAPP_HI ->
  disjoint_from (rs_W2 lo sp fb) (sh A) (nsh n).
Proof.
  intros lo sp fb A n H1 H2 HA Hn HT. pose proof aceil_facts as (AF & _).
  pose proof (sh_ge_lowsh A HA) as L. pose proof (sh_nsh_high A n HA Hn HT) as U.
  unfold rs_W2. cbn [disjoint_from fst snd]. unfold AG_HTTP_CAT, ALOWSH_LO, AHI_LO in *. repeat split; lia.
Qed.
Lemma W2_outside_sh : forall lo (sp : word) fb x, aceil <= lo -> aceil <= fb + 8 -> 0 <= x -> x + 1 <= AAPP_HI -> outside (rs_W2 lo sp fb) (sh x).
Proof.
  intros lo sp fb x H1 H2 Hx HT. pose proof aceil_facts as (AF & _).
  pose proof (sh_ge_lowsh x Hx) as L. pose proof (sh_nsh_high x 1 Hx ltac:(lia) HT) as U. unfold nsh in U. change ((1 + 7) / 8) with 1 in U.
  unfold rs_W2. cbn [outside fst snd]. unfold AG_HTTP_CAT, ALOWSH_LO, AHI_LO in *. repeat split; lia.
Qed.

(* [comment removed for export] *)
Lemma W2_write_ok : forall s LB m LF m1 lo (sp : word) fb, as_RHEAP H s LB m -> as_RFS H LF m1 -> aceil <= lo -> aceil <= fb + 8 ->
  Forall (aclient_write_ok H LB) (rs_W2 lo sp fb) /\ Forall (afs_write_ok H LF) (rs_W2 lo sp fb) /\ Forall aconst_ok (rs_W2 lo sp fb).
Proof.
  intros s LB m LF m1 lo sp fb RH RF H1 H2. pose proof (RFS_fsb _ HH _ _ RF) as (B1 & B2 & B3 & B4).
  destruct (stack_window_ok' H HH s LB m LF lo (bv_unsigned sp + -104) RH H1) as (S1 & S2 & S3).
  destruct (stack_window_ok' H HH s LB m LF (fb + 8) (fb + 24) RH H2) as (T1 & T2 & T3).
  assert (C1 : aclient_write_ok H LB (AG_HTTP_CAT, AG_HTTP_CAT + 64)).
  { right; left. unfold aimg_client_w, ATLS_PRIV_LO, ATP, AG_HTTP_CAT. cbn [fst snd]. right; right; right; left. clear. lia. }
  assert (C2 : afs_write_ok H LF (AG_HTTP_CAT, AG_HTTP_CAT + 64)).
  { left. cbn [fst snd]. unfold AIMG_TOP, ATLS_PRIV_LO, ATP, AG_HTTP_CAT in *. clear - B1. lia. }
  pose proof pwin_httpcat as [(C3 & _) _].
  unfold rs_W2. split; [| split]; (apply Forall_cons; [| apply Forall_cons; [| apply Forall_cons; [| apply Forall_nil]]]); assumption.
Qed.
